using System.ComponentModel.DataAnnotations;
using RailwayReservation.Models;

namespace RailwayReservation.ViewModels
{
    /// <summary>Admin form for creating / editing a user (password is generated by system).</summary>
    public class UserFormViewModel
    {
        public int UserId { get; set; }

        [Required, StringLength(50, MinimumLength = 3)]
        [RegularExpression("^[A-Za-z0-9_.]+$", ErrorMessage = "Only letters, digits, underscore and dot are allowed.")]
        [Display(Name = "User Name")]
        public string UserName { get; set; }

        [Required, StringLength(100)]
        [Display(Name = "Full Name")]
        public string FullName { get; set; }

        [Display(Name = "User Type")]
        public UserType UserType { get; set; }

        [Display(Name = "Active")]
        public bool IsActive { get; set; }
    }
}